from itertools import combinations as iter_combinations

def combinations(target, size, exclude):
    """
    Return all possible combinations of distinct Sudoku digits (1-9) of length `size`
    that sum to `target`, excluding any digits in `exclude`.

    Each combination is returned as a list of integers in ascending order.
    The returned list is sorted lexicographically.
    """
    # Normalize exclude into a set of ints between 1 and 9
    excluded = set()
    for v in exclude:
        if isinstance(v, int):
            iv = v
        else:
            try:
                iv = int(v)
            except Exception:
                continue
        if 1 <= iv <= 9:
            excluded.add(iv)

    choices = [d for d in range(1, 10) if d not in excluded]

    results = []
    for combo in iter_combinations(choices, size):
        if sum(combo) == target:
            results.append(list(combo))

    results.sort()
    return results
